mapper.select:
SELECT a.resource_ref FROM audit_event a WHERE a.audit_id=#{auditId} AND a.subject_id=#{userId}
  AND a.project_id <=> #{projectId} AND a.action=#{action} AND a.result='SUCCESS' AND a.reason_code IS NULL
  AND a.request_id=#{requestId} AND a.trace_id=#{requestId} AND a.schema_version='1.0.0'
  AND a.schema_manifest_sha256=#{schemaManifest} AND a.created_by=#{userId} AND a.classification=#{classification}

SELECT e.payload FROM outbox_event e WHERE e.event_id=#{eventId}
  AND e.aggregate_id=#{collectionId} AND e.aggregate_revision=#{resulting} AND e.event_type=#{action}
  AND JSON_UNQUOTE(JSON_EXTRACT(e.payload,'$.creation.operation_id'))=#{operationId}

mapper.update:
UPDATE collection_head SET title=#{title},current_version=#{versionId},revision=#{resulting},updated_at=#{now}
WHERE collection_id=#{collectionId} AND revision=#{expected}
AND current_version=#{baseId}AND current_version IS NULL
